// Generated by agent-workspace. Calls the control plane's session retention route on a Cron Trigger.
export default {
  async scheduled(_controller, env) {
    if (!env.CONTROL_PLANE_URL) throw new Error('CONTROL_PLANE_URL is not set');
    if (!env.CRON_SECRET) throw new Error('CRON_SECRET is not set');
    const base = env.CONTROL_PLANE_URL.replace(/\/+$/, '');
    const response = await globalThis.fetch(base + '/api/cron/retention', {
      headers: { authorization: 'Bearer ' + env.CRON_SECRET },
    });
    if (!response.ok) throw new Error('The retention route answered ' + response.status);
  },
};
